import AppKit
import CryptoKit
import ImageIO
import UniformTypeIdentifiers

public enum PasteboardMarkers {
    public static let restored = "com.bunniesinc.clipboard.restored"
    public static let source = "org.nspasteboard.source"
    public static let remote = "com.apple.is-remote-clipboard"

    // nspasteboard.org conventions, plus the private markers password managers still use.
    private static let ignored: Set<String> = [
        restored,
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "de.petermaurer.TransientPasteboardType",
        "Pasteboard generator type",
        "com.agilebits.onepassword",
        "com.typeit4me.clipping",
        "net.antelle.keeweb",
    ]

    private static let unsaved: Set<String> = [
        source,
        remote,
        "com.apple.pasteboard.promised-file-url",
        "com.apple.pasteboard.NSFilePromiseID",
    ]

    public static func shouldIgnore(types: Set<String>) -> Bool {
        !types.isDisjoint(with: ignored)
    }

    public static func shouldStore(uti: String, byteCount: Int) -> Bool {
        if unsaved.contains(uti) { return false }
        // dyn.* types are usually legacy duplicates of a declared type, so large ones aren't worth keeping.
        if uti.hasPrefix("dyn."), byteCount > 4_000_000 { return false }
        return byteCount <= 256_000_000
    }
}

public struct ClipDraft: Sendable {
    public let kind: ClipKind
    public let text: String?
    public let items: [[Representation]]
    public let hash: String
    public let source: ClipSource
    public let byteSize: Int64
    public let pixelWidth: Int?
    public let pixelHeight: Int?
    public let thumbnail: Data?
    public let isSecret: Bool
}

public enum BuildResult: Sendable {
    case clip(ClipDraft)
    case skippedEmpty
    case skippedSecret
}

public enum ClipBuilder {
    private static let plainTextTypes = [
        "public.utf8-plain-text", "public.utf16-external-plain-text", "public.utf16-plain-text",
    ]
    private static let imageTypes = [
        "public.png", "public.tiff", "public.jpeg", "public.heic", "org.webmproject.webp", "com.compuserve.gif",
        "com.microsoft.bmp",
    ]
    private static let thumbnailPixels = 720

    public static func build(items rawItems: [[Representation]], source: ClipSource, secrets: SecretHandling) -> BuildResult {
        let items = rawItems
            .map { $0.filter { PasteboardMarkers.shouldStore(uti: $0.uti, byteCount: $0.data.count) } }
            .filter { !$0.isEmpty }
        guard !items.isEmpty else { return .skippedEmpty }
        let byteSize = items.joined().reduce(Int64(0)) { $0 + Int64($1.data.count) }

        let paths = filePaths(from: items)
        if !paths.isEmpty {
            let text = paths.joined(separator: "\n")
            return .clip(draft(.file, text: text, items: items, identity: "file:" + text, source: source, byteSize: byteSize))
        }

        let text = items.compactMap(plainText(from:)).joined(separator: "\n")
        let hasText = !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        let isSecret = hasText && SecretDetector.containsSecret(text)
        if isSecret, secrets == .skip { return .skippedSecret }

        let textKind = hasText ? ClipClassifier.classify(text: text, sourceBundleID: source.bundleID) : nil
        // Browsers put the image's URL next to its bytes on "Copy Image", which is still an image copy.
        if textKind == nil || textKind == .link,
            let image = items.joined().first(where: { imageTypes.contains($0.uti) }),
            let thumbnail = Thumbnailer.make(from: image.data, maxPixels: thumbnailPixels) {
            let digest = SHA256.hash(data: image.data).map { String(format: "%02x", $0) }.joined()
            return .clip(
                draft(
                    .image, text: hasText ? text : nil, items: items, identity: "image:" + digest, source: source,
                    byteSize: byteSize, pixelWidth: thumbnail.width, pixelHeight: thumbnail.height,
                    thumbnail: thumbnail.png, isSecret: isSecret))
        }

        if let textKind {
            return .clip(
                draft(
                    textKind, text: text, items: items, identity: "text:" + text, source: source, byteSize: byteSize,
                    isSecret: isSecret))
        }

        // Only app-private or empty-string types. Whitespace alone never produces a useful card.
        let opaque = items.joined().filter { !plainTextTypes.contains($0.uti) }
        guard !opaque.isEmpty else { return .skippedEmpty }
        let digest = opaque.reduce(into: SHA256()) { hasher, rep in
            hasher.update(data: Data(rep.uti.utf8))
            hasher.update(data: rep.data)
        }.finalize().map { String(format: "%02x", $0) }.joined()
        return .clip(draft(.text, text: nil, items: items, identity: "data:" + digest, source: source, byteSize: byteSize))
    }

    private static func draft(
        _ kind: ClipKind, text: String?, items: [[Representation]], identity: String, source: ClipSource,
        byteSize: Int64, pixelWidth: Int? = nil, pixelHeight: Int? = nil, thumbnail: Data? = nil, isSecret: Bool = false
    ) -> ClipDraft {
        let hash = SHA256.hash(data: Data(identity.utf8)).map { String(format: "%02x", $0) }.joined()
        return ClipDraft(
            kind: kind, text: text, items: items, hash: hash, source: source, byteSize: byteSize,
            pixelWidth: pixelWidth, pixelHeight: pixelHeight, thumbnail: thumbnail, isSecret: isSecret)
    }

    static func filePaths(from items: [[Representation]]) -> [String] {
        items.compactMap { reps in
            guard let rep = reps.first(where: { $0.uti == "public.file-url" }),
                let string = String(data: rep.data, encoding: .utf8),
                let url = URL(string: string.trimmingCharacters(in: .whitespacesAndNewlines))
            else { return nil }
            return ((url as NSURL).filePathURL ?? url).path
        }
    }

    static func plainText(from reps: [Representation]) -> String? {
        for type in plainTextTypes {
            guard let rep = reps.first(where: { $0.uti == type }) else { continue }
            let encoding: String.Encoding = type == "public.utf8-plain-text" ? .utf8 : .utf16
            if let string = String(data: rep.data, encoding: encoding), !string.isEmpty { return string }
        }
        if let rep = reps.first(where: { $0.uti == "public.url" }), let string = String(data: rep.data, encoding: .utf8) {
            return string
        }
        if let rep = reps.first(where: { $0.uti == "public.rtf" }),
            let attributed = NSAttributedString(rtf: rep.data, documentAttributes: nil) {
            return attributed.string
        }
        if let rep = reps.first(where: { $0.uti == "com.apple.flat-rtfd" }),
            let attributed = NSAttributedString(rtfd: rep.data, documentAttributes: nil) {
            return attributed.string
        }
        if let rep = reps.first(where: { $0.uti == "public.html" }), let html = String(data: rep.data, encoding: .utf8) {
            return stripTags(html)
        }
        return nil
    }

    // NSAttributedString's HTML importer spins up WebKit and must stay on the main thread; capture runs off it.
    private static func stripTags(_ html: String) -> String {
        html.replacingOccurrences(of: "(?s)<(script|style)[^>]*>.*?</\\1>", with: " ", options: .regularExpression)
            .replacingOccurrences(of: "<[^>]+>", with: " ", options: .regularExpression)
            .replacingOccurrences(of: "&nbsp;", with: " ")
            .replacingOccurrences(of: "&lt;", with: "<")
            .replacingOccurrences(of: "&gt;", with: ">")
            .replacingOccurrences(of: "&quot;", with: "\"")
            .replacingOccurrences(of: "&#39;", with: "'")
            .replacingOccurrences(of: "&amp;", with: "&")
            .replacingOccurrences(of: "[ \\t]+", with: " ", options: .regularExpression)
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }
}

public enum Thumbnailer {
    public struct Output: Sendable {
        public let png: Data
        public let width: Int
        public let height: Int
    }

    public static func make(from data: Data, maxPixels: Int) -> Output? {
        guard let source = CGImageSourceCreateWithData(data as CFData, nil), CGImageSourceGetCount(source) > 0 else {
            return nil
        }
        let properties = CGImageSourceCopyPropertiesAtIndex(source, 0, nil) as? [CFString: Any]
        let options: [CFString: Any] = [
            kCGImageSourceCreateThumbnailFromImageAlways: true,
            kCGImageSourceCreateThumbnailWithTransform: true,
            kCGImageSourceThumbnailMaxPixelSize: maxPixels,
        ]
        guard let image = CGImageSourceCreateThumbnailAtIndex(source, 0, options as CFDictionary) else { return nil }
        let output = NSMutableData()
        guard
            let destination = CGImageDestinationCreateWithData(
                output as CFMutableData, UTType.png.identifier as CFString, 1, nil)
        else { return nil }
        CGImageDestinationAddImage(destination, image, nil)
        guard CGImageDestinationFinalize(destination) else { return nil }
        return Output(
            png: output as Data,
            width: properties?[kCGImagePropertyPixelWidth] as? Int ?? image.width,
            height: properties?[kCGImagePropertyPixelHeight] as? Int ?? image.height)
    }
}
